//! Replays the persisted-tier golden vectors of `tests/golden/persisted` (generated by the C#
//! `PersistedGoldenVectorGenerator`, see `tests/golden/README.md`) through the Rust builder, merger, readers and stack,
//! over tables and blob files held in memory.
//!
//! Every table the Rust tier builds or merges must hash to the C# one, every blob file must match the C# file byte for
//! byte, and every bloom must report the C# key count and size, after every step; every read through the stack must
//! return what C# returned. The C# tables and blob runs the vectors carry inline are read back with the Rust readers.
//! Arena placement and the catalog rows' locations are the storage layer's and are not replayed here: the rows are
//! decoded and re-encoded, and their sizes checked against the tables.
//!
//! The model of the tier mirrors the C# calls the generator makes: the repository's persisted walks
//! (`AssemblePersistedSnapshotsForCompaction`, `AssembleSnapshots`), `ShareBloomAcrossRange`, the blob manager's choice
//! of file, and the loader's bloom rebuild.

mod common;

use std::collections::{BTreeMap, BTreeSet, HashSet, VecDeque};
use std::path::{Path, PathBuf};
use std::sync::Arc;

use common::persisted::{Blobs, MemBlobs, MemSnapshot, convert, merge, new_blobs, snapshot_from_records};
use common::{hex, hex20, hex32, to_hex};
use flatdb_core::bloom::BloomFilter;
use flatdb_core::persisted::bloom_keys;
use flatdb_core::persisted::builder::estimate_size;
use flatdb_core::persisted::codec::{self, BlobRange, CATALOG_KEY_SIZE};
use flatdb_core::persisted::io::ByteReader;
use flatdb_core::persisted::list::PersistedSnapshotList;
use flatdb_core::persisted::page_layout::{NodeRef, PAGE_SIZE};
use flatdb_core::persisted::reader::{read_blob_range, read_ref_ids, resolve_trie_rlp};
use flatdb_core::persisted::scanner::Scanner;
use flatdb_core::persisted::sorted::enumerator::SortedTableEnumerator;
use flatdb_core::persisted::sorted::table_reader;
use flatdb_core::persisted::stack::PersistedSnapshotStack;
use flatdb_core::schedule::CompactionSchedule;
use flatdb_core::snapshot::{Snapshot, SnapshotTier};
use flatdb_core::types::{Account, StateId, TreePath, U256};
use serde_json::Value;
use sha2::{Digest, Sha256};

type Result<T> = std::result::Result<T, String>;

fn golden_files() -> Vec<PathBuf> {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/persisted");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&directory)
        .unwrap_or_else(|error| panic!("{}: {error}", directory.display()))
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.extension().is_some_and(|extension| extension == "json"))
        .collect();
    files.sort();
    files
}

#[test]
fn persisted_golden_vectors_replay_byte_for_byte() {
    let files = golden_files();
    assert_eq!(files.len(), 5, "the five C# scenarios");
    let failures = files
        .iter()
        .filter_map(|file| {
            let vector: Value = serde_json::from_str(&std::fs::read_to_string(file).unwrap()).unwrap();
            replay(&vector)
                .err()
                .map(|error| format!("{}: {error}", file.file_name().unwrap().to_string_lossy()))
        })
        .collect::<Vec<_>>();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Every table and blob run the C# vectors carry inline, read with the Rust readers: a full scan returns the records
/// in strictly ascending order and every one of them seeks back to the same value; the scanner views cover the
/// records of their columns; the ref-ids and blob range match, and every state and storage node reference resolves
/// against the C# blob bytes, the resolved items covering the blob run.
#[test]
fn rust_readers_read_every_csharp_table() {
    let mut tables = 0;
    for file in golden_files() {
        let vector: Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
        for step in vector["steps"].as_array().unwrap() {
            for snapshot in step["state"]["snapshots"].as_array().into_iter().flatten() {
                let Some(table_hex) = snapshot["tableHex"].as_str() else {
                    continue;
                };
                let table = hex(table_hex);
                assert_eq!(to_hex(&Sha256::digest(&table)), snapshot["table"].as_str().unwrap());
                read_csharp_table(&table, snapshot).unwrap_or_else(|error| panic!("{}: {error}", file.display()));
                tables += 1;
            }
        }
    }
    assert!(tables >= 10, "only {tables} inline tables");
}

fn read_csharp_table(table: &[u8], snapshot: &Value) -> Result<()> {
    let reader = ByteReader::new(table);
    let mut enumerator = SortedTableEnumerator::new(&reader);
    let mut previous: Option<Vec<u8>> = None;
    let mut records = 0;
    let (mut per_address_records, mut node_records, mut slot_records) = (0, 0, 0);
    while enumerator.move_next(&reader).map_err(|error| error.to_string())? {
        let key = enumerator.current_key().to_vec();
        if previous.as_ref().is_some_and(|previous| previous >= &key) {
            return Err(format!("keys out of order at {}", to_hex(&key)));
        }
        let (offset, length) = enumerator.current_value();
        let value = &table[offset..offset + length];
        let sought = table_reader::get(&reader, &key).map_err(|error| error.to_string())?;
        if sought != Some(value) {
            return Err(format!(
                "{} seeks to {sought:?}, the scan read {}",
                to_hex(&key),
                to_hex(value)
            ));
        }
        match key[0] {
            0xFA..=0xFD => node_records += 1,
            0xFE if key[21] == 0xFF => slot_records += 1,
            0xFE => per_address_records += 1,
            _ => {}
        }
        records += 1;
        previous = Some(key);
    }
    if records == 0 {
        return Err("an empty scan".to_owned());
    }

    let range = read_blob_range(&reader).map_err(|error| error.to_string())?;
    let expected_range = blob_range_of(&snapshot["blobRange"]);
    if range != expected_range {
        return Err(format!("blob range {range:?}, C# {expected_range:?}"));
    }
    let ref_ids = read_ref_ids(&reader).map_err(|error| error.to_string())?;
    if !range.is_empty() && !ref_ids.contains(&range.blob_arena_id) {
        return Err(format!("ref-ids {ref_ids:?} miss the blob range's file"));
    }

    // The scanner covers the same records: one per-address group per address, every slot, every trie node.
    let scanner = Scanner::new(&reader);
    let mut per_addresses = scanner.per_addresses();
    let (mut addresses, mut scanned_slots, mut accounts_and_flags) = (0, 0, 0);
    while let Some(entry) = per_addresses.next_address().map_err(|error| error.to_string())? {
        addresses += 1;
        accounts_and_flags += usize::from(entry.has_account) + usize::from(entry.self_destruct_flag.is_some());
        per_addresses.account().map_err(|error| error.to_string())?;
        while per_addresses.next_slot().map_err(|error| error.to_string())?.is_some() {
            scanned_slots += 1;
        }
    }
    let mut scanned_nodes = 0;
    for mut nodes in [scanner.state_nodes(), scanner.storage_nodes()] {
        while let Some(node) = nodes.next_node().map_err(|error| error.to_string())? {
            if node.node_ref.len() != 6 {
                return Err(format!("a node reference of {} bytes", node.node_ref.len()));
            }
            scanned_nodes += 1;
        }
    }
    if (accounts_and_flags, scanned_slots, scanned_nodes) != (per_address_records, slot_records, node_records) {
        return Err(format!(
            "the scanner saw {accounts_and_flags} accounts and flags, {scanned_slots} slots and {scanned_nodes} nodes; \
             the table holds {per_address_records}, {slot_records} and {node_records}"
        ));
    }
    if addresses > per_address_records + slot_records {
        return Err(format!("{addresses} addresses"));
    }

    // A base's node references resolve to items of its own blob run, which, in offset order, tile the run but for
    // the zero padding before an item that would cross a page.
    if let Some(blob_hex) = snapshot["blobHex"].as_str() {
        let mut file = vec![0u8; range.offset as usize];
        file.extend_from_slice(&hex(blob_hex));
        let blobs = MemBlobs(BTreeMap::from([(range.blob_arena_id, file)]));
        let mut items = BTreeSet::new();
        for mut nodes in [scanner.state_nodes(), scanner.storage_nodes()] {
            while let Some(node) = nodes.next_node().map_err(|error| error.to_string())? {
                let node_ref = NodeRef::read(node.node_ref);
                let rlp = resolve_trie_rlp(node.node_ref, &blobs).map_err(|error| error.to_string())?;
                if node_ref.blob_arena_id != range.blob_arena_id {
                    return Err(format!("{node_ref:?} outside the blob range's file"));
                }
                items.insert((node_ref.rlp_data_offset as usize, rlp.len()));
            }
        }
        let run = &blobs[&range.blob_arena_id];
        let mut end = range.offset as usize;
        for (offset, length) in items {
            let gap = run
                .get(end..offset)
                .ok_or_else(|| format!("the item at {offset} overlaps the one before"))?;
            if gap.len() >= PAGE_SIZE || gap.iter().any(|&byte| byte != 0) {
                return Err(format!("{} unexplained bytes before the item at {offset}", gap.len()));
            }
            end = offset + length;
        }
        if end != (range.offset + range.length) as usize {
            return Err(format!(
                "the items end at {end}, the blob range at {}",
                range.offset + range.length
            ));
        }
    }
    Ok(())
}

fn blob_range_of(value: &Value) -> BlobRange {
    BlobRange {
        blob_arena_id: value["id"].as_u64().unwrap() as u16,
        offset: value["offset"].as_i64().unwrap(),
        length: value["length"].as_i64().unwrap(),
    }
}

fn state_id(value: &Value) -> StateId {
    StateId::new(value["block"].as_u64().unwrap(), hex32(value["root"].as_str().unwrap()))
}

fn tree_path(value: &Value) -> TreePath {
    TreePath::new(
        hex32(value["path"].as_str().unwrap()),
        value["length"].as_u64().unwrap() as u8,
    )
}

fn tier_of(value: &Value) -> SnapshotTier {
    codec::tier_from_byte(value.as_u64().unwrap() as u8).unwrap()
}

fn height(state: &StateId) -> i64 {
    state.block_number as i64
}

const PERSISTED_TIERS: [SnapshotTier; 4] = [
    SnapshotTier::PersistedBase,
    SnapshotTier::PersistedSmallCompacted,
    SnapshotTier::PersistedCompactSized,
    SnapshotTier::PersistedLargeCompacted,
];

/// The enumeration order of the blob manager's `HashSet<ushort>` of files with room: entries in slot order, a removed
/// entry's slot reused by the next add, last freed first.
#[derive(Default)]
struct DotNetHashSetOrder {
    slots: Vec<Option<u16>>,
    free: Vec<usize>,
}

impl DotNetHashSetOrder {
    fn add(&mut self, id: u16) {
        if self.slots.contains(&Some(id)) {
            return;
        }
        match self.free.pop() {
            Some(slot) => self.slots[slot] = Some(id),
            None => self.slots.push(Some(id)),
        }
    }

    fn remove(&mut self, id: u16) {
        if let Some(slot) = self.slots.iter().position(|entry| *entry == Some(id)) {
            self.slots[slot] = None;
            self.free.push(slot);
        }
    }

    fn ids(&self) -> Vec<u16> {
        self.slots.iter().flatten().copied().collect()
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Step {
    Skip,
    Traverse,
    Win,
    WinAndStop,
}

struct Tier {
    bits_per_key: f64,
    blob_file_size: i64,
    schedule: CompactionSchedule,
    blobs: Blobs,
    mutable_blobs: DotNetHashSetOrder,
    next_blob_id: u16,
    buckets: BTreeMap<u8, BTreeMap<StateId, Arc<MemSnapshot>>>,
    /// The catalog rows, as the C# state lists them (their locations are placement this replay does not model).
    catalog: BTreeMap<Vec<u8>, Vec<u8>>,
}

impl Tier {
    fn new(config: &Value) -> Self {
        Self {
            bits_per_key: config["bloomBitsPerKey"].as_f64().unwrap(),
            blob_file_size: config["arenaFileSizeBytes"].as_i64().unwrap(),
            schedule: CompactionSchedule::new(
                config["compactSize"].as_u64().unwrap(),
                config["persistedSnapshotMaxCompactSize"].as_u64().unwrap(),
                config["compactionOffset"].as_u64().unwrap(),
            )
            .unwrap(),
            blobs: new_blobs(),
            mutable_blobs: DotNetHashSetOrder::default(),
            next_blob_id: 0,
            buckets: PERSISTED_TIERS
                .iter()
                .map(|&tier| (codec::tier_byte(tier), BTreeMap::new()))
                .collect(),
            catalog: BTreeMap::new(),
        }
    }

    fn bucket(&mut self, tier: SnapshotTier) -> &mut BTreeMap<StateId, Arc<MemSnapshot>> {
        self.buckets.get_mut(&codec::tier_byte(tier)).unwrap()
    }

    fn get(&self, tier: SnapshotTier, to: &StateId) -> Option<&Arc<MemSnapshot>> {
        self.buckets[&codec::tier_byte(tier)].get(to)
    }

    fn count(&self) -> usize {
        self.buckets.values().map(BTreeMap::len).sum()
    }

    /// `BlobArenaManager.CreateWriter`: the first file with room for `estimate`, dropping those without, else a new one.
    fn choose_blob_file(&mut self, estimate: i64) -> u16 {
        let blobs = self.blobs.read().unwrap();
        let mut chosen = None;
        for id in self.mutable_blobs.ids() {
            if blobs[&id].len() as i64 + estimate <= self.blob_file_size {
                chosen = Some(id);
                break;
            }
            self.mutable_blobs.remove(id);
        }
        drop(blobs);
        match chosen {
            Some(id) => {
                self.mutable_blobs.remove(id);
                id
            }
            None => {
                let id = self.next_blob_id;
                self.next_blob_id += 1;
                self.blobs.write().unwrap().insert(id, Vec::new());
                id
            }
        }
    }

    fn convert(&mut self, step: &Value) -> Result<()> {
        let (from, to) = (state_id(&step["from"]), state_id(&step["to"]));
        let snapshot = snapshot_from_records(from, to, &hex(step["records"].as_str().unwrap_or_default()));
        let estimate = estimate_size(&snapshot);
        if estimate != step["estimate"].as_i64().unwrap() {
            return Err(format!("estimate {estimate}, C# {}", step["estimate"]));
        }
        let blob_id = self.choose_blob_file(estimate);
        let (persisted, output) = convert(&snapshot, &self.blobs, blob_id, self.bits_per_key);
        if self.blobs.read().unwrap()[&blob_id].len() < self.blob_file_size as usize {
            self.mutable_blobs.add(blob_id);
        }
        let nodes = snapshot
            .state_nodes()
            .filter(|(_, node)| !node.is_hash_only_placeholder())
            .count()
            + snapshot
                .storage_nodes()
                .filter(|(_, node)| !node.is_hash_only_placeholder())
                .count();
        if output.written_nodes.len() != nodes {
            return Err(format!("{} written nodes of {nodes}", output.written_nodes.len()));
        }
        self.bucket(SnapshotTier::PersistedBase).insert(to, Arc::new(persisted));
        Ok(())
    }

    fn compact(&mut self, to: StateId, start: u64, compact_sized: bool) -> Result<()> {
        let chain = self.walk(to, &PERSISTED_TIERS_WIDEST_FIRST, {
            let mut winner_height = i64::MAX;
            move |from, _| {
                if height(&from) < start as i64 {
                    Step::Skip
                } else if from.block_number == start {
                    Step::WinAndStop
                } else if height(&from) < winner_height {
                    winner_height = height(&from);
                    Step::Win
                } else {
                    Step::Traverse
                }
            }
        });
        if chain.len() < 2 {
            return Err(format!(
                "the window of {to:?} from {start} holds {} snapshots",
                chain.len()
            ));
        }

        let mut owners: Vec<&Arc<BloomFilter>> = Vec::new();
        for source in &chain {
            if !owners.iter().any(|owner| Arc::ptr_eq(owner, &source.bloom)) {
                owners.push(&source.bloom);
            }
        }
        let capacity = owners.iter().map(|bloom| bloom.count() as i64).sum::<i64>();
        let tier = if compact_sized {
            SnapshotTier::PersistedCompactSized
        } else if self.schedule.is_large_compaction_boundary(to.block_number) {
            SnapshotTier::PersistedLargeCompacted
        } else {
            SnapshotTier::PersistedSmallCompacted
        };
        let bloom = match (self.bits_per_key > 0.0 && capacity > 0, tier) {
            (false, _) => BloomFilter::always_true(),
            (true, SnapshotTier::PersistedSmallCompacted) => BloomFilter::new(1, self.bits_per_key).unwrap(),
            (true, _) => BloomFilter::new(capacity, self.bits_per_key).unwrap(),
        };
        let sources = chain.iter().map(Arc::as_ref).collect::<Vec<_>>();
        let merged = Arc::new(merge(&sources, tier, bloom));
        let (from, merged_to, shared) = (merged.from, merged.to, merged.bloom.clone());
        self.bucket(tier).insert(merged_to, merged);
        // C# shares at every large boundary, the CompactSized merge there included.
        if self.schedule.is_large_compaction_boundary(to.block_number) {
            self.share_bloom_across_range(from, merged_to, &shared);
        }
        Ok(())
    }

    /// `WalkAndAssemble` over the persisted buckets.
    fn walk(
        &self,
        start: StateId,
        priority: &[SnapshotTier],
        mut decide: impl FnMut(StateId, SnapshotTier) -> Step,
    ) -> Vec<Arc<MemSnapshot>> {
        let mut queue = VecDeque::from([(start, None)]);
        let mut seen = HashSet::from([start]);
        let mut visited: Vec<(Arc<MemSnapshot>, Option<usize>)> = Vec::new();
        let mut winner = None;
        'walk: while let Some((current, parent)) = queue.pop_front() {
            for &tier in priority {
                let Some(snapshot) = self.get(tier, &current) else {
                    continue;
                };
                let step = decide(snapshot.from, tier);
                if step == Step::Skip || !seen.insert(snapshot.from) {
                    continue;
                }
                visited.push((snapshot.clone(), parent));
                if step != Step::Traverse {
                    winner = Some(visited.len() - 1);
                }
                if step == Step::WinAndStop {
                    break 'walk;
                }
                queue.push_back((snapshot.from, Some(visited.len() - 1)));
            }
        }

        let mut chain = Vec::new();
        let mut at = winner;
        while let Some(index) = at {
            chain.push(visited[index].0.clone());
            at = visited[index].1;
        }
        chain
    }

    /// `ShareBloomAcrossRange`: down the base chain from `to`, every snapshot of `(from, to]` not on `bloom` yet
    /// becomes a twin on it.
    fn share_bloom_across_range(&mut self, from: StateId, to: StateId, bloom: &Arc<BloomFilter>) {
        let mut current = to;
        while height(&current) > height(&from) {
            let Some(base_parent) = self.get(SnapshotTier::PersistedBase, &current).map(|base| base.from) else {
                break;
            };
            for tier in [
                SnapshotTier::PersistedBase,
                SnapshotTier::PersistedSmallCompacted,
                SnapshotTier::PersistedLargeCompacted,
                SnapshotTier::PersistedCompactSized,
            ] {
                let Some(snapshot) = self.get(tier, &current).cloned() else {
                    continue;
                };
                if Arc::ptr_eq(&snapshot.bloom, bloom)
                    || height(&snapshot.from) < height(&from)
                    || height(&snapshot.to) > height(&to)
                {
                    continue;
                }
                self.bucket(tier)
                    .insert(current, Arc::new(snapshot.with_bloom(bloom.clone())));
            }
            if base_parent == current {
                break;
            }
            current = base_parent;
        }
    }

    /// The loader: every catalog row reopened with the always-true bloom, unreferenced blob files swept, then the
    /// widest chain's blooms rebuilt and shared. A refused catalog fails it with the C# message.
    fn reload(&mut self) -> Result<()> {
        let packed = self
            .catalog
            .iter()
            .flat_map(|(key, value)| {
                [
                    &(key.len() as u32).to_le_bytes()[..],
                    key,
                    &(value.len() as u32).to_le_bytes(),
                    value,
                ]
                .concat()
            })
            .collect::<Vec<_>>();
        let entries = codec::parse_rows(&packed).map_err(|error| error.to_string())?;

        let previous = std::mem::take(&mut self.buckets);
        self.buckets = PERSISTED_TIERS
            .iter()
            .map(|&tier| (codec::tier_byte(tier), BTreeMap::new()))
            .collect();
        for entry in &entries {
            let snapshot = previous[&codec::tier_byte(entry.tier)]
                .get(&entry.to)
                .filter(|snapshot| snapshot.from == entry.from)
                .ok_or_else(|| format!("no table for the catalog entry {entry:?}"))?;
            if snapshot.table.len() as i64 != entry.location.size {
                return Err(format!(
                    "catalog size {} of a {}-byte table",
                    entry.location.size,
                    snapshot.table.len()
                ));
            }
            let reopened = snapshot.with_bloom(Arc::new(BloomFilter::always_true()));
            self.bucket(entry.tier).insert(entry.to, Arc::new(reopened));
        }

        let referenced = self
            .buckets
            .values()
            .flat_map(BTreeMap::values)
            .flat_map(|snapshot| read_ref_ids(&ByteReader::new(&snapshot.table)).unwrap())
            .collect::<BTreeSet<_>>();
        self.blobs.write().unwrap().retain(|id, _| referenced.contains(id));

        if self.bits_per_key <= 0.0 || entries.is_empty() {
            return Ok(());
        }
        let head = self
            .buckets
            .values()
            .filter_map(|bucket| bucket.keys().max())
            .max()
            .copied()
            .unwrap();
        let committed = entries.iter().map(|entry| entry.from).min_by_key(height).unwrap();
        if head == committed {
            return Ok(());
        }
        let widest = self.walk(head, &ASSEMBLE_PRIORITY, |from, _| {
            if height(&from) < height(&committed) || from == committed {
                Step::WinAndStop
            } else if from.block_number == committed.block_number {
                Step::Skip
            } else {
                Step::Traverse
            }
        });
        for snapshot in widest {
            let bloom = bloom_keys::rebuild(&ByteReader::new(&snapshot.table), self.bits_per_key).unwrap();
            self.share_bloom_across_range(snapshot.from, snapshot.to, &Arc::new(bloom));
        }
        Ok(())
    }

    fn check_state(&mut self, state: &Value) -> Result<()> {
        self.catalog = state["catalog"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| (hex(row[0].as_str().unwrap()), hex(row[1].as_str().unwrap())))
            .collect();
        let mut rows = BTreeMap::new();
        for (key, value) in &self.catalog {
            let (Ok(key), Ok(value)) = (
                <[u8; CATALOG_KEY_SIZE]>::try_from(key.as_slice()),
                <[u8; codec::CATALOG_VALUE_SIZE]>::try_from(value.as_slice()),
            ) else {
                continue;
            };
            let entry = codec::decode_value(&value).map_err(|error| error.to_string())?;
            if codec::encode_row(&entry) != (key, value) {
                return Err(format!("catalog row {} does not re-encode", to_hex(&key)));
            }
            rows.insert(key.to_vec(), entry);
        }

        let mut seen = 0;
        for expected in state["snapshots"].as_array().unwrap() {
            let key = hex(expected["key"].as_str().unwrap());
            let entry = rows.get(&key).ok_or("a snapshot without a catalog row")?;
            let snapshot = self
                .get(entry.tier, &entry.to)
                .filter(|snapshot| snapshot.from == entry.from)
                .ok_or_else(|| format!("no {:?} snapshot {:?} -> {:?}", entry.tier, entry.from, entry.to))?;
            seen += 1;
            let label = format!(
                "{:?} {} -> {}",
                entry.tier, entry.from.block_number, entry.to.block_number
            );
            if to_hex(&Sha256::digest(&snapshot.table)) != expected["table"].as_str().unwrap() {
                let detail = expected["tableHex"]
                    .as_str()
                    .map(|csharp| first_difference(&snapshot.table, &hex(csharp)))
                    .unwrap_or_default();
                return Err(format!(
                    "{label}: the table differs from C# ({} bytes){detail}",
                    snapshot.table.len()
                ));
            }
            if snapshot.table.len() as i64 != entry.location.size {
                return Err(format!("{label}: catalog size {}", entry.location.size));
            }
            let range = read_blob_range(&ByteReader::new(&snapshot.table)).map_err(|error| error.to_string())?;
            if range != blob_range_of(&expected["blobRange"]) {
                return Err(format!("{label}: blob range {range:?}"));
            }
            let bloom = (snapshot.bloom.count() as i64, snapshot.bloom.data_bytes() as i64);
            let csharp = (
                expected["bloomCount"].as_i64().unwrap(),
                expected["bloomDataBytes"].as_i64().unwrap(),
            );
            if bloom != csharp {
                return Err(format!("{label}: bloom (count, bytes) {bloom:?}, C# {csharp:?}"));
            }
            if let Some(blob_hex) = expected["blobHex"].as_str() {
                let blobs = self.blobs.read().unwrap();
                let run = &blobs[&range.blob_arena_id][range.offset as usize..(range.offset + range.length) as usize];
                if run != hex(blob_hex) {
                    return Err(format!("{label}: the blob run differs"));
                }
            }
        }
        if seen != self.count() {
            return Err(format!("{} snapshots, C# lists {seen}", self.count()));
        }

        let blobs = self.blobs.read().unwrap();
        let mut blob_files = 0;
        for file in state["files"].as_array().unwrap() {
            let path = file[0].as_str().unwrap();
            let Some(id) = path
                .strip_prefix("blob/blob_")
                .and_then(|name| name.strip_suffix(".bin"))
            else {
                continue;
            };
            let bytes = blobs
                .get(&id.parse::<u16>().unwrap())
                .ok_or_else(|| format!("no {path}"))?;
            if bytes.len() as u64 != file[1].as_u64().unwrap()
                || to_hex(&Sha256::digest(bytes)) != file[2].as_str().unwrap()
            {
                return Err(format!("{path}: {} bytes differ from C#'s {}", bytes.len(), file[1]));
            }
            blob_files += 1;
        }
        if blob_files != blobs.len() {
            return Err(format!("{} blob files, C# has {blob_files}", blobs.len()));
        }
        Ok(())
    }

    fn reads(&self, step: &Value) -> Result<()> {
        let mut stack = PersistedSnapshotList::empty();
        for layer in step["stack"].as_array().unwrap() {
            let (from, to) = (state_id(&layer["from"]), state_id(&layer["to"]));
            let snapshot = self
                .get(tier_of(&layer["tier"]), &to)
                .filter(|snapshot| snapshot.from == from)
                .ok_or_else(|| format!("no stack snapshot {from:?} -> {to:?}"))?;
            stack.push(snapshot.clone());
        }
        let in_memory = step["inMemory"]
            .as_array()
            .unwrap()
            .iter()
            .map(|block| {
                snapshot_from_records(
                    state_id(&block["from"]),
                    state_id(&block["to"]),
                    &hex(block["records"].as_str().unwrap_or_default()),
                )
            })
            .collect::<Vec<_>>();
        let bundle = Bundle {
            in_memory,
            stack: PersistedSnapshotStack::new(stack),
        };

        for expected in step["expect"].as_array().unwrap() {
            let address = || hex20(expected["address"].as_str().unwrap());
            let actual = match expected["op"].as_str().unwrap() {
                "getAccount" => account_json(bundle.get_account(&address())),
                "selfDestructIdx" => Value::from(bundle.self_destruct_index(&address())),
                "getSlot" => {
                    let slot = U256::from_be_bytes(&hex32(expected["slot"].as_str().unwrap()));
                    let index = expected["selfDestructIdx"].as_i64().unwrap() as isize;
                    bundle
                        .get_slot(&address(), &slot, index)
                        .map_or(Value::Null, |value| Value::from(to_hex(&value.to_be_bytes())))
                }
                "loadStateRlp" => rlp_json(bundle.load_state_rlp(&tree_path(&expected["path"]))),
                "loadStorageRlp" => rlp_json(bundle.load_storage_rlp(
                    &hex32(expected["addressHash"].as_str().unwrap()),
                    &tree_path(&expected["path"]),
                )),
                op => return Err(format!("unknown read {op}")),
            };
            if !same_result(&actual, &expected["result"]) {
                return Err(format!("{expected}: Rust read {actual}"));
            }
        }
        Ok(())
    }
}

const PERSISTED_TIERS_WIDEST_FIRST: [SnapshotTier; 4] = [
    SnapshotTier::PersistedLargeCompacted,
    SnapshotTier::PersistedCompactSized,
    SnapshotTier::PersistedSmallCompacted,
    SnapshotTier::PersistedBase,
];

/// `AssemblePolicy.EdgePriority` without its in-memory tiers, which a reload has none of.
const ASSEMBLE_PRIORITY: [SnapshotTier; 4] = PERSISTED_TIERS_WIDEST_FIRST;

fn first_difference(rust: &[u8], csharp: &[u8]) -> String {
    let at = rust.iter().zip(csharp).take_while(|(a, b)| a == b).count();
    format!("; C# is {} bytes, first difference at byte {at}", csharp.len())
}

/// The C# `ReadOnlySnapshotBundle` reads the vectors were taken through: the in-memory snapshots newest first, then
/// the persisted stack, over an empty persistence.
struct Bundle {
    in_memory: Vec<Snapshot>,
    stack: PersistedSnapshotStack<MemSnapshot>,
}

impl Bundle {
    fn get_account(&self, address: &[u8; 20]) -> Option<Account> {
        if let Some(account) = self
            .in_memory
            .iter()
            .rev()
            .find_map(|snapshot| snapshot.try_get_account(address))
        {
            return account;
        }
        self.stack.try_get_account(address).unwrap().flatten()
    }

    fn self_destruct_index(&self, address: &[u8; 20]) -> i64 {
        let persisted = self.stack.len();
        if let Some(index) = self
            .in_memory
            .iter()
            .rposition(|snapshot| snapshot.has_self_destruct(address))
        {
            return (persisted + index) as i64;
        }
        self.stack
            .try_get_self_destruct(address)
            .unwrap()
            .map_or(-1, |index| index as i64)
    }

    fn get_slot(&self, address: &[u8; 20], slot: &U256, self_destruct_index: isize) -> Option<U256> {
        let persisted = self.stack.len();
        for (index, snapshot) in self.in_memory.iter().enumerate().rev() {
            if let Some(value) = snapshot.try_get_storage(address, slot) {
                return value;
            }
            if (persisted + index) as isize <= self_destruct_index {
                return None;
            }
        }
        self.stack
            .try_get_slot(address, slot, self_destruct_index)
            .unwrap()
            .flatten()
    }

    fn load_state_rlp(&self, path: &TreePath) -> Option<Vec<u8>> {
        // The newest in-memory node decides, but a placeholder falls through to the stack.
        let newest = self
            .in_memory
            .iter()
            .rev()
            .find_map(|snapshot| snapshot.try_get_state_node(path));
        if let Some(node) = newest.filter(|node| !node.is_hash_only_placeholder()) {
            return Some(node.rlp.to_vec());
        }
        self.stack.try_load_state_rlp(path).unwrap()
    }

    fn load_storage_rlp(&self, address_hash: &[u8; 32], path: &TreePath) -> Option<Vec<u8>> {
        let newest = self
            .in_memory
            .iter()
            .rev()
            .find_map(|snapshot| snapshot.try_get_storage_node(address_hash, path));
        if let Some(node) = newest.filter(|node| !node.is_hash_only_placeholder()) {
            return Some(node.rlp.to_vec());
        }
        self.stack.try_load_storage_rlp(address_hash, path).unwrap()
    }
}

fn account_json(account: Option<Account>) -> Value {
    account.map_or(Value::Null, |account| {
        serde_json::json!({
            "nonce": to_hex(&U256::from_u64(account.nonce).to_be_bytes()),
            "balance": to_hex(&account.balance.to_be_bytes()),
            "storageRoot": to_hex(&account.storage_root),
            "codeHash": to_hex(&account.code_hash),
        })
    })
}

fn rlp_json(rlp: Option<Vec<u8>>) -> Value {
    rlp.map_or(Value::Null, |rlp| Value::from(to_hex(&rlp)))
}

/// Results compare as JSON, but for account quantities, which C# writes as minimal hex.
fn same_result(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Object(actual), Value::Object(expected)) => {
            actual.len() == expected.len()
                && actual
                    .iter()
                    .all(|(name, value)| match (name.as_str(), value, &expected[name]) {
                        ("nonce" | "balance", Value::String(actual), Value::String(expected)) => {
                            quantity(actual) == quantity(expected)
                        }
                        (_, value, expected) => value == expected,
                    })
        }
        _ => actual == expected,
    }
}

fn quantity(text: &str) -> U256 {
    U256::from_be_slice(&hex(&format!("{:0>64}", text.trim_start_matches("0x"))))
}

fn replay(vector: &Value) -> Result<()> {
    let mut tier = Tier::new(&vector["config"]);
    for (index, step) in vector["steps"].as_array().unwrap().iter().enumerate() {
        let kind = step["kind"].as_str().unwrap();
        let outcome = match kind {
            "convert" => tier.convert(step),
            "compact" => {
                let to = state_id(&step["to"]);
                let size = tier.schedule.get_persisted_snapshot_compact_size(to.block_number) as i64;
                let start = (to.block_number as i64 - size).max(step["persistedBlock"].as_i64().unwrap());
                tier.compact(to, start as u64, false)
            }
            "compactSized" => {
                let to = state_id(&step["to"]);
                let start = to.block_number - tier.schedule.get_compact_size(to.block_number);
                tier.compact(to, start, true)
            }
            "reload" => match (tier.reload(), step["error"].as_str()) {
                (Err(error), Some(expected)) if error == expected => Ok(()),
                (Err(error), _) => Err(error),
                (Ok(()), Some(expected)) => Err(format!("the reload succeeded where C# refused: {expected}")),
                (Ok(()), None) => Ok(()),
            },
            "catalogPut" => {
                tier.catalog
                    .insert(hex(step["key"].as_str().unwrap()), hex(step["value"].as_str().unwrap()));
                Ok(())
            }
            "reads" => tier.reads(step),
            other => Err(format!("unknown step {other}")),
        };
        outcome
            .and_then(|()| match step.get("state") {
                Some(state) => tier.check_state(state),
                None => Ok(()),
            })
            .map_err(|error| format!("step {index} ({kind}): {error}"))?;
    }
    Ok(())
}
